select.if:
WITH TD_MOVE AS ( SELECT B.TECH, A.OPE_NO, SUM(A.WAFER_QTY) AS TD_MOVE FROM A1MFG.PR_MOVE_LIST_TD A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.TECH_FLAG ='Y' WHERE 1=1
GROUP BY B.TECH, A.OPE_NO ) , YD_MOVE AS ( SELECT B.TECH, A.OPE_NO, SUM(A.WAFER_QTY) AS YD_MOVE FROM A1MFG.PH_MOVE_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.TECH_FLAG ='Y' WHERE 1=1 AND A.SHIFT_DATE =TO_CHAR(SYSDATE -7.5/24 -1,'YYYYMMDD')
GROUP BY B.TECH, A.OPE_NO ) , PRE7D_MOVE AS ( SELECT B.TECH, A.OPE_NO, ROUND(SUM(A.WAFER_QTY)/7,0) AS PRE7D_MOVE FROM A1MFG.PH_MOVE_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.TECH_FLAG ='Y' WHERE 1=1 AND A.SHIFT_DATE <= TO_CHAR(SYSDATE -7.5/24 -1,'YYYYMMDD') AND A.SHIFT_DATE >=TO_CHAR(SYSDATE -7.5/24 -7,'YYYYMMDD')
GROUP BY B.TECH, A.OPE_NO ) , WIP_DATA AS ( SELECT B.TECH, A.* FROM A1MFG.PR_WIP_SUM_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.TECH_FLAG ='Y' WHERE 1=1
) , WIP_SUMMARY AS ( SELECT A.TECH , A.OPE_NO , MIN(A.LOT_PRIORITY) AS LOT_PRIORITY , SUM(CASE WHEN A.STATE IN('RUN','HOLD','WAIT') THEN A.WAFER_QTY END) TOTAL_WIP , SUM(CASE WHEN A.STATE='WAIT' AND A.REMAIN_QTIME <> 0.0 THEN 1 ELSE 0 END) Q_WAIT_WIP , SUM(CASE WHEN A.STATE='HOLD' AND A.REMAIN_QTIME <> 0.0 THEN 1 ELSE 0 END) Q_HOLD_WIP , SUM(CASE WHEN A.STATE='RUN' AND A.REMAIN_QTIME <> 0.0 THEN 1 ELSE 0 END) Q_RUN_WIP , SUM(CASE WHEN A.STATE='WAIT' AND A.SHL_FLAG='Y' AND A.LOT_PRIORITY >=1 AND A.LOT_PRIORITY <=69 THEN 1 ELSE 0 END) SHL_WAIT_WIP , SUM(CASE WHEN A.STATE='HOLD' AND A.SHL_FLAG='Y' AND A.LOT_PRIORITY >=1 AND A.LOT_PRIORITY <=69 THEN 1 ELSE 0 END) SHL_HOLD_WIP , SUM(CASE WHEN A.STATE='RUN' AND A.SHL_FLAG='Y' AND A.LOT_PRIORITY >=1 AND A.LOT_PRIORITY <=69 THEN 1 ELSE 0 END) SHL_RUN_WIP , MAX(CASE WHEN A.OPE_NO=A.TARGET_OP_NO THEN A.QTIME_SPEC ELSE 0 END) QTIME_SPEC , SUM(CASE WHEN A.STATE='RUN' THEN A.WAFER_QTY END) RUN_WIP , SUM(CASE WHEN A.STATE='BANK' THEN A.WAFER_QTY END) BANK_WIP , SUM(CASE WHEN A.STATE='WAIT' THEN A.WAFER_QTY END) WAIT_WIP , AVG(CASE WHEN A.STATE='WAIT' THEN A.WAIT_TIME ELSE NULL END) WAIT_TIME , SUM(CASE WHEN A.STATE='HOLD' THEN A.WAFER_QTY END ) HOLD_WIP , AVG(CASE WHEN A.STATE='HOLD' THEN A.HOLD_TIME ELSE NULL END) HOLD_TIME --, SUM(CASE WHEN A.STATE='CAPBANK' THEN QTY ELSE 0 END) A_MFG_BANK , SUM(CASE WHEN SUBSTR(A.PRODG1,1,4)='NX11' THEN A.WAFER_QTY END) NEX , SUM(CASE WHEN A.SGS_VALUE IS NOT NULL THEN A.WAFER_QTY END) SGS_WIP FROM WIP_DATA A GROUP BY A.TECH, A.OPE_NO ) , BACKUP_WIP AS ( SELECT B.TECH , A.OPE_NO , SUM(CASE WHEN A.STATE IN('RUN','HOLD','WAIT') THEN A.WAFER_QTY END) BACKUP_WIP , SUM(CASE WHEN A.STATE='RUN' THEN A.WAFER_QTY END) BACKUP_RUN_WIP , SUM(CASE WHEN A.STATE='WAIT' THEN A.WAFER_QTY END) BACKUP_WAIT_WIP , AVG(CASE WHEN A.STATE='WAIT' THEN A.WAIT_TIME ELSE NULL END) BACKUP_WAIT_TIME , SUM(CASE WHEN A.STATE='HOLD' THEN A.WAFER_QTY END ) BACKUP_HOLD_WIP , AVG(CASE WHEN A.STATE='HOLD' THEN A.HOLD_TIME ELSE NULL END) BACKUP_HOLD_TIME FROM A1MFG.PR_WIP_SUM_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.TECH_FLAG ='Y' WHERE 1=1
AND A.FAB='N1A1' AND A.LOCATION_FAB='N1A3'
AND A.FAB='N1A3' AND A.LOCATION_FAB='N1A1'
AND A.FAB='N1A1' AND A.LOCATION_FAB='N1A1'
GROUP BY B.TECH, A.OPE_NO ) , CUTLINE_DATA AS ( SELECT A.TECH, A.PROC_STAGE, OPE_NO, A.CUT_COMMENT AS CUT_COMMENT FROM A3MFGYW1.PROFILE_TECH_CUT_COMMENT@TO_A3MFG A WHERE A.TECH =#{tech}
) , UPDATE_TIME AS ( SELECT MAX(UPDATE_TIME) AS UPDATE_TIME FROM A1MFG.PR_WIP_SUM_LIST ) SELECT TO_CHAR(L.UPDATE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS UPDATE_TIME , A.OPE_SEQ , A.MODULE , A.EQP_G , A.PROC_STAGE , A.OPE_NO , A.FOUP_CATEGORY , A.S_OP , A.QTIME , CASE WHEN A.RATE IS NOT NULL THEN A.RATE || '%' END AS SAMPLING , ROUND(A.STD_CT_REMAIN,1) AS STD_CT_REMAIN , B.LOT_PRIORITY , B.TOTAL_WIP , SUM(NVL(B.TOTAL_WIP,0)) OVER (ORDER BY A.OPE_SEQ DESC) AS TOTAL_WIP_SUM , CASE WHEN B.Q_WAIT_WIP IS NOT NULL AND B.Q_WAIT_WIP <> 0 THEN 'Y' ELSE 'N' END AS Q_WAIT_FLAG , CASE WHEN B.Q_HOLD_WIP IS NOT NULL AND B.Q_HOLD_WIP <> 0 THEN 'Y' ELSE 'N' END AS Q_HOLD_FLAG , CASE WHEN B.Q_RUN_WIP IS NOT NULL AND B.Q_RUN_WIP <> 0 THEN 'Y' ELSE 'N' END AS Q_RUN_FLAG , CASE WHEN B.SHL_WAIT_WIP IS NOT NULL AND B.SHL_WAIT_WIP <> 0 THEN 'Y' ELSE 'N' END AS SHL_WAIT_FLAG , CASE WHEN B.SHL_HOLD_WIP IS NOT NULL AND B.SHL_HOLD_WIP <> 0 THEN 'Y' ELSE 'N' END AS SHL_HOLD_FLAG , CASE WHEN B.SHL_RUN_WIP IS NOT NULL AND B.SHL_RUN_WIP <> 0 THEN 'Y' ELSE 'N' END AS SHL_RUN_FLAG , B.RUN_WIP , B.WAIT_WIP , ROUND(B.WAIT_TIME,1) AS WAIT_TIME , B.HOLD_WIP , ROUND(B.HOLD_TIME,1) AS HOLD_TIME , B.BANK_WIP , B.NEX , C.BACKUP_WIP , SUM(NVL(C.BACKUP_WIP,0)) OVER (ORDER BY A.OPE_SEQ DESC) AS BACKUP_SUM_WIP , C.BACKUP_RUN_WIP , C.BACKUP_WAIT_WIP , ROUND(C.BACKUP_WAIT_TIME,1) AS BACKUP_WAIT_TIME , C.BACKUP_HOLD_WIP , ROUND(C.BACKUP_HOLD_TIME,1) AS BACKUP_HOLD_TIME , E.TD_MOVE , F.YD_MOVE , G.PRE7D_MOVE , M.OPE_NO AS CUTLINE_OPE_NO , B.SGS_WIP FROM A1MFG.TECH_FLOW_MAINTAIN A LEFT JOIN WIP_SUMMARY B ON A.TECH =B.TECH AND A.OPE_NO = B.OPE_NO LEFT JOIN BACKUP_WIP C ON A.TECH =C.TECH AND A.OPE_NO = C.OPE_NO LEFT JOIN TD_MOVE E ON A.TECH =E.TECH AND A.OPE_NO = E.OPE_NO LEFT JOIN YD_MOVE F ON A.TECH =F.TECH AND A.OPE_NO = F.OPE_NO LEFT JOIN PRE7D_MOVE G ON A.TECH =G.TECH AND A.OPE_NO = G.OPE_NO LEFT JOIN UPDATE_TIME L ON 1=1 LEFT JOIN CUTLINE_DATA M ON A.TECH =M.TECH AND A.OPE_NO = M.OPE_NO WHERE 1=1 AND A.TECH =#{tech}
AND (A.MODULE LIKE '%' OR A.MODULE IS NULL)
AND A.MODULE IN ('WET','CMP')
AND A.MODULE=#{module}
AND (A.EQP_G LIKE '%' OR A.EQP_G IS NULL)
AND A.EQP_G=#{eqpg}
ORDER BY A.OPE_SEQ

WITH TD_MOVE AS ( SELECT B.TECH, A.FINAL_PRODG1 AS PRODG1, A.OPE_NO, SUM(A.WAFER_QTY) AS TD_MOVE FROM A1MFG.PR_MOVE_LIST_TD A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.PRODG1 =#{prodg} WHERE 1=1
GROUP BY B.TECH, A.FINAL_PRODG1, A.OPE_NO ) , YD_MOVE AS ( SELECT B.TECH, A.FINAL_PRODG1 AS PRODG1, A.OPE_NO, SUM(A.WAFER_QTY) AS YD_MOVE FROM A1MFG.PH_MOVE_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.PRODG1 =#{prodg} WHERE 1=1
AND A.SHIFT_DATE =TO_CHAR(SYSDATE -7.5/24 -1,'YYYYMMDD') GROUP BY B.TECH, A.FINAL_PRODG1, A.OPE_NO ) , PRE7D_MOVE AS ( SELECT B.TECH, A.FINAL_PRODG1 AS PRODG1, A.OPE_NO, ROUND(SUM(A.WAFER_QTY)/7,0) AS PRE7D_MOVE FROM A1MFG.PH_MOVE_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.PRODG1 =#{prodg} WHERE 1=1
AND A.SHIFT_DATE <= TO_CHAR(SYSDATE -7.5/24 -1,'YYYYMMDD') AND A.SHIFT_DATE >=TO_CHAR(SYSDATE -7.5/24 -7,'YYYYMMDD') GROUP BY B.TECH, A.FINAL_PRODG1, A.OPE_NO ) , WIP_DATA AS ( SELECT B.TECH, A.* FROM A1MFG.PR_WIP_SUM_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.PRODG1 =#{prodg} WHERE 1=1
) , WIP_SUMMARY AS ( SELECT A.TECH , A.OPE_NO , MIN(A.LOT_PRIORITY) AS LOT_PRIORITY , SUM(CASE WHEN A.STATE IN('RUN','HOLD','WAIT') THEN A.WAFER_QTY END) TOTAL_WIP , SUM(CASE WHEN A.STATE='WAIT' AND A.REMAIN_QTIME <> 0.0 THEN 1 ELSE 0 END) Q_WAIT_WIP , SUM(CASE WHEN A.STATE='HOLD' AND A.REMAIN_QTIME <> 0.0 THEN 1 ELSE 0 END) Q_HOLD_WIP , SUM(CASE WHEN A.STATE='RUN' AND A.REMAIN_QTIME <> 0.0 THEN 1 ELSE 0 END) Q_RUN_WIP , SUM(CASE WHEN A.STATE='WAIT' AND A.SHL_FLAG='Y' AND A.LOT_PRIORITY >=1 AND A.LOT_PRIORITY <=69 THEN 1 ELSE 0 END) SHL_WAIT_WIP , SUM(CASE WHEN A.STATE='HOLD' AND A.SHL_FLAG='Y' AND A.LOT_PRIORITY >=1 AND A.LOT_PRIORITY <=69 THEN 1 ELSE 0 END) SHL_HOLD_WIP , SUM(CASE WHEN A.STATE='RUN' AND A.SHL_FLAG='Y' AND A.LOT_PRIORITY >=1 AND A.LOT_PRIORITY <=69 THEN 1 ELSE 0 END) SHL_RUN_WIP , MAX(CASE WHEN A.OPE_NO=A.TARGET_OP_NO THEN A.QTIME_SPEC ELSE 0 END) QTIME_SPEC , SUM(CASE WHEN A.STATE='RUN' THEN A.WAFER_QTY END) RUN_WIP , SUM(CASE WHEN A.STATE='BANK' THEN A.WAFER_QTY END) BANK_WIP , SUM(CASE WHEN A.STATE='WAIT' THEN A.WAFER_QTY END) WAIT_WIP , AVG(CASE WHEN A.STATE='WAIT' THEN A.WAIT_TIME ELSE NULL END) WAIT_TIME , SUM(CASE WHEN A.STATE='HOLD' THEN A.WAFER_QTY END ) HOLD_WIP , AVG(CASE WHEN A.STATE='HOLD' THEN A.HOLD_TIME ELSE NULL END) HOLD_TIME , SUM(CASE WHEN SUBSTR(A.PRODG1,1,4)='NX11' THEN A.WAFER_QTY END) NEX , SUM(CASE WHEN A.SGS_VALUE IS NOT NULL THEN A.WAFER_QTY END) SGS_WIP FROM WIP_DATA A GROUP BY A.TECH, A.OPE_NO ) , BACKUP_WIP AS ( SELECT B.TECH , A.FINAL_PRODG1 AS PRODG1 , A.OPE_NO , SUM(CASE WHEN A.STATE IN('RUN','HOLD','WAIT') THEN A.WAFER_QTY END) BACKUP_WIP , SUM(CASE WHEN A.STATE='RUN' THEN A.WAFER_QTY END) BACKUP_RUN_WIP , SUM(CASE WHEN A.STATE='WAIT' THEN A.WAFER_QTY END) BACKUP_WAIT_WIP , AVG(CASE WHEN A.STATE='WAIT' THEN A.WAIT_TIME ELSE NULL END) BACKUP_WAIT_TIME , SUM(CASE WHEN A.STATE='HOLD' THEN A.WAFER_QTY END ) BACKUP_HOLD_WIP , AVG(CASE WHEN A.STATE='HOLD' THEN A.HOLD_TIME ELSE NULL END) BACKUP_HOLD_TIME FROM A1MFG.PR_WIP_SUM_LIST A JOIN A1MFG.PRODUCT_TECH_COMBINE B ON A.FINAL_PRODG1 = B.PRODG1 AND B.TECH =#{tech} AND B.PRODG1 =#{prodg} WHERE 1=1
AND A.FAB='N1A1' AND A.LOCATION_FAB='N1A3'
AND A.FAB='N1A3' AND A.LOCATION_FAB='N1A1'
AND A.FAB='N1A1' AND A.LOCATION_FAB='N1A1'
GROUP BY B.TECH, A.FINAL_PRODG1, A.OPE_NO ) , TO_OPE_DATA AS ( SELECT DISTINCT FINAL_PRODG1 AS PRODG1 , FROM_OPE_NO , TO_OPE_NO , MIN(SUBSTR(TO_OPE_NO, 4, 5)) AS S_OP FROM A1MFG.FLOW_QTIME_CONSTRAINT_ALL WHERE FINAL_PRODG1 =#{prodg} GROUP BY FINAL_PRODG1, FROM_OPE_NO, TO_OPE_NO ) , QTIME_DATA AS ( SELECT DISTINCT FINAL_PRODG1 AS PRODG1 , FROM_OPE_NO , TO_OPE_NO , MIN(QTIME_LIMIT) AS QTIME FROM A1MFG.FLOW_QTIME_CONSTRAINT_ALL WHERE FINAL_PRODG1 =#{prodg} GROUP BY FINAL_PRODG1, TO_OPE_NO, FROM_OPE_NO ) , SAMPLING_DATA AS ( SELECT DISTINCT FINAL_PRODG1 AS PRODG1 , OPE_NO , ROUND(AVG(CASE WHEN MAINCHIP='1' THEN NVL(SAMPLING_RATE,0) END *100.00),1) AS RATE FROM A1MFG.V_FLOW_SAMPLING_RATE_ALL WHERE FINAL_PRODG1 =#{prodg} GROUP BY FINAL_PRODG1, OPE_NO ) , CUTLINE_DATA AS ( SELECT A.PRODG1, A.CUTLINE_OPE_NO FROM A3MFGYW1.OUTPUT_CUTLINE@TO_A3MFG A WHERE A.CUTLINE_NEED>=1 AND A.PRODG1 =#{prodg}
) , UPDATE_TIME AS ( SELECT MAX(UPDATE_TIME) AS UPDATE_TIME FROM A1MFG.PR_WIP_SUM_LIST ) SELECT DISTINCT TO_CHAR(L.UPDATE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS UPDATE_TIME , A.OPER_SEQ AS OPE_SEQ , A.MODULE , A.EQP_G , A.PROC_STAGE , A.OPER_NO AS OPE_NO , A.FOUP_CATEGORY , J.S_OP , H.QTIME , CASE WHEN K.RATE IS NOT NULL THEN K.RATE || '%' END AS SAMPLING , ROUND(A.REMAIN_CT_ACC/24,1) AS STD_CT_REMAIN , B.LOT_PRIORITY , B.TOTAL_WIP , SUM(NVL(B.TOTAL_WIP,0)) OVER (ORDER BY A.OPER_SEQ DESC) AS TOTAL_WIP_SUM , CASE WHEN B.Q_WAIT_WIP IS NOT NULL AND B.Q_WAIT_WIP <> 0 THEN 'Y' ELSE 'N' END AS Q_WAIT_FLAG , CASE WHEN B.Q_HOLD_WIP IS NOT NULL AND B.Q_HOLD_WIP <> 0 THEN 'Y' ELSE 'N' END AS Q_HOLD_FLAG , CASE WHEN B.Q_RUN_WIP IS NOT NULL AND B.Q_RUN_WIP <> 0 THEN 'Y' ELSE 'N' END AS Q_RUN_FLAG , CASE WHEN B.SHL_WAIT_WIP IS NOT NULL AND B.SHL_WAIT_WIP <> 0 THEN 'Y' ELSE 'N' END AS SHL_WAIT_FLAG , CASE WHEN B.SHL_HOLD_WIP IS NOT NULL AND B.SHL_HOLD_WIP <> 0 THEN 'Y' ELSE 'N' END AS SHL_HOLD_FLAG , CASE WHEN B.SHL_RUN_WIP IS NOT NULL AND B.SHL_RUN_WIP <> 0 THEN 'Y' ELSE 'N' END AS SHL_RUN_FLAG , B.RUN_WIP , B.WAIT_WIP , ROUND(B.WAIT_TIME,1) AS WAIT_TIME , B.HOLD_WIP , ROUND(B.HOLD_TIME,1) AS HOLD_TIME , B.BANK_WIP , B.NEX , C.BACKUP_WIP , SUM(NVL(C.BACKUP_WIP,0)) OVER (ORDER BY A.OPER_SEQ DESC) AS BACKUP_SUM_WIP , C.BACKUP_RUN_WIP , C.BACKUP_WAIT_WIP , ROUND(C.BACKUP_WAIT_TIME,1) AS BACKUP_WAIT_TIME , C.BACKUP_HOLD_WIP , ROUND(C.BACKUP_HOLD_TIME,1) AS BACKUP_HOLD_TIME , E.TD_MOVE , F.YD_MOVE , G.PRE7D_MOVE , M.CUTLINE_OPE_NO , B.SGS_WIP FROM A1MFG.MST_FLOW_PRODG_ALL_FLOW A LEFT JOIN WIP_SUMMARY B ON A.OPER_NO = B.OPE_NO LEFT JOIN BACKUP_WIP C ON A.OPER_NO = C.OPE_NO LEFT JOIN TD_MOVE E ON A.OPER_NO = E.OPE_NO LEFT JOIN YD_MOVE F ON A.OPER_NO = F.OPE_NO LEFT JOIN PRE7D_MOVE G ON A.OPER_NO = G.OPE_NO LEFT JOIN QTIME_DATA H ON A.PRODG1=H.PRODG1 AND A.OPER_NO =H.FROM_OPE_NO LEFT JOIN SAMPLING_DATA K ON A.PRODG1=K.PRODG1 AND A.OPER_NO =K.OPE_NO LEFT JOIN TO_OPE_DATA J ON A.PRODG1=J.PRODG1 AND A.OPER_NO =J.TO_OPE_NO LEFT JOIN CUTLINE_DATA M ON A.PRODG1=M.PRODG1 AND A.OPER_NO =M.CUTLINE_OPE_NO LEFT JOIN UPDATE_TIME L ON 1=1 WHERE 1=1 AND A.PRODG1 =#{prodg}
AND (A.MODULE LIKE '%' OR A.MODULE IS NULL)
AND A.MODULE IN ('WET','CMP')
AND A.MODULE=#{module}
AND (A.EQP_G LIKE '%' OR A.EQP_G IS NULL)
AND A.EQP_G=#{eqpg}
ORDER BY A.OPER_SEQ

mapper.select:
SELECT DISTINCT A.CUSTOMER , A.CUSTOMER2 AS CT_G , A.FINAL_PRODG1 AS PRODG1 , A.FINAL_PRODSPEC_ID AS PRODSPEC_ID , A.FLOW_KEY , A.FROM_OPE_NO , A.TO_OPE_NO , (A.TO_SEQ -A.FROM_SEQ) AS QTIME_STEP , A.QTIME_LIMIT FROM A1MFG.FLOW_QTIME_CONSTRAINT_ALL A WHERE 1=1
AND A.FINAL_PRODG1 =#{tech}
AND A.FINAL_PRODG1 =#{prodg}
AND A.FROM_OPE_NO =#{openo}

SELECT DISTINCT A.CUSTOMER , A.CUSTOMER2 AS CT_G , A.FINAL_PRODG1 AS PRODG1 , A.PRODSPEC_ID , A.MODULE , A.OPE_NO , CASE WHEN A.MAINCHIP=1 THEN '★' END AS MAIN_SUFFIX , CASE WHEN A.SAMPLING_RATE IS NOT NULL THEN A.SAMPLING_RATE*100 || '%' END AS SAMPLING_RATE FROM A1MFG.V_FLOW_SAMPLING_RATE_ALL A WHERE 1=1 AND A.OPE_NO =#{openo}
AND A.FINAL_PRODG1 =#{tech}
AND A.FINAL_PRODG1 =#{prodg}
ORDER BY A.PRODSPEC_ID

select.if:
SELECT DISTINCT A.EQPG_LABEL, A.EQPG_VALUE FROM ( SELECT 'ALL' EQPG_LABEL, 'all' EQPG_VALUE , '' AS MODULE FROM DUAL UNION ALL SELECT DISTINCT EQP_G AS EQPG_LABEL, EQP_G AS EQPG_VALUE , MODULE FROM A1MFG.TECH_FLOW_MAINTAIN WHERE EQP_G IS NOT NULL AND TECH =#{tech}
AND (MODULE LIKE '%' OR MODULE IS NULL)
AND MODULE IN ('WET','CMP')
AND MODULE=#{module}
)A
ORDER BY A.EQPG_LABEL

SELECT DISTINCT A.EQPG_LABEL, A.EQPG_VALUE FROM ( SELECT 'ALL' EQPG_LABEL, 'all' EQPG_VALUE , '' AS MODULE FROM DUAL UNION ALL SELECT DISTINCT EQP_G AS EQPG_LABEL, EQP_G AS EQPG_VALUE , MODULE FROM A1MFG.MST_FLOW_PRODG_ALL_FLOW WHERE EQP_G IS NOT NULL AND PRODG1 =#{prodg}
AND (MODULE LIKE '%' OR MODULE IS NULL)
AND MODULE IN ('WET','CMP')
AND MODULE=#{module}
)A
ORDER BY A.EQPG_LABEL
